_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Convert a valid Roman numeral (I through MMMCMXCIX) to its integer value.

    Iterates left to right, adding each symbol's value; when a smaller value
    precedes a larger value (a subtractive pair like IV or CM), it is
    subtracted instead.
    """
    total = 0
    n = len(s)
    for i, ch in enumerate(s):
        value = _VALUES[ch]
        if i + 1 < n and value < _VALUES[s[i + 1]]:
            total -= value
        else:
            total += value
    return total

def int_to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError("Input must be between 1 and 3999 inclusive")

    values = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result = []
    for value, symbol in values:
        while n >= value:
            result.append(symbol)
            n -= value

    return "".join(result)

