def run_length_decode(s: str) -> str:
    if not s:
        return ""

    # Regex to match valid pattern: letter followed by one or more digits
    pattern = re.compile(r'([a-zA-Z])(\d+)')
    matches = pattern.findall(s)

    # Check if the concatenation of matches covers the entire string without gaps
    reconstructed = ''.join(letter + digits for letter, digits in matches)
    if reconstructed != s:
        raise ValueError("Malformed run-length encoded string")

    # Check for zero counts
    for letter, digits in matches:
        if int(digits) == 0:
            raise ValueError("Zero count not allowed")

    # Decode
    result = []
    for letter, digits in matches:
        result.append(letter * int(digits))

    return ''.join(result)

