_PAIRS = {")": "(", "]": "[", "}": "{"}
_OPENERS = frozenset(_PAIRS.values())


def is_balanced(s: str) -> bool:
    """Return True iff all brackets in `s` are correctly matched and nested.

    Recognized bracket types: (), [], {}. All other characters are ignored.
    An empty string or a string containing no brackets returns True.
    """
    stack = []
    for ch in s:
        if ch in _OPENERS:
            stack.append(ch)
        elif ch in _PAIRS:
            if not stack or stack.pop() != _PAIRS[ch]:
                return False
    return not stack

