def flatten(items: list) -> list:
    """
    Recursively flattens arbitrarily nested lists into a single flat list.

    Args:
        items (list): The list to flatten.

    Returns:
        list: A single flat list containing all non-list elements.

    Raises:
        TypeError: If the input 'items' is not a list.
    """
    if not isinstance(items, list):
        raise TypeError(f"Expected list, got {type(items).__name__}")

    result = []

    def _recursive_flatten(current_item):
        if isinstance(current_item, list):
            for element in current_item:
                _recursive_flatten(element)
        else:
            result.append(current_item)

    # Start the recursion
    for item in items:
        _recursive_flatten(item)

    # Telemetry: Report the size of the flattened list for monitoring performance
