def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching closed intervals.

    Args:
        intervals: List of (start, end) tuples with start <= end.

    Returns:
        List of merged (start, end) tuples sorted by start.

    Raises:
        ValueError: If any interval has start > end.
    """
    if not intervals:
        return []

    for start, end in intervals:
        if start > end:
            raise ValueError(
                f"Invalid interval ({start}, {end}): start must be <= end"
            )

    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0]]
    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        # Closed intervals that touch (start == last_end) also merge.
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

def transpose(matrix: list[list]) -> list[list]:
    if not matrix:
        return []

    # Check rectangularity
    num_rows = len(matrix)
    num_cols = len(matrix[0])
    for row in matrix:
        if len(row) != num_cols:
            raise ValueError("Input matrix is not rectangular")

    # Empty rows case
    if num_cols == 0:
        return []

    # Transpose
    result = [[matrix[row][col] for row in range(num_rows)] for col in range(num_cols)]
    return result

