def is_valid_ipv4(s: str) -> bool:
    """
    Returns True iff s is exactly four decimal octets in the range 0-255 
    separated by single dots. Each octet must have no leading zeros, 
    except that the single digit "0" is allowed.
    """
    # Split the string by dots
    parts = s.split('.')

    # There must be exactly four parts
    if len(parts) != 4:
        return False

    for part in parts:
        # Check if part is empty (handles cases like "1..1.1" or ".1.1.1")
        if not part:
            return False

        # Check if part contains only digits
        if not part.isdigit():
            return False

        # Check for leading zeros:
        # If length > 1, the first character cannot be '0'
        if len(part) > 1 and part[0] == '0':
            return False

        # Convert to integer and check range 0-255
        try:
            val = int(part)
            if not (0 <= val <= 255):
                return False
        except ValueError:
            return False

    return True

from urllib.parse import unquote_plus

def parse_query_string(qs: str) -> dict[str, list[str]]:
    # Remove optional leading '?'
    if qs.startswith('?'):
        qs = qs[1:]

    # Handle empty or only '?' input
    if not qs:
        return {}

    result: dict[str, list[str]] = {}

    # Split by '&' and skip empty segments
    for segment in qs.split('&'):
        if not segment:
            continue

        if '=' in segment:
            key, value = segment.split('=', 1)
        else:
            key = segment
            value = ''

        # Percent-decode and convert '+' to space
        key = unquote_plus(key)
        value = unquote_plus(value)

        # Add to result
        if key not in result:
            result[key] = []
        result[key].append(value)

    return result

