    # Remove optional leading '?'
    if qs.startswith("?"):
        qs = qs[1:]

    # Handle empty or only '?' input
    if not qs:
        return {}

    result: dict[str, list[str]] = {}

    # Split on '&' and skip empty segments
    for segment in qs.split("&"):
        if not segment:
            continue

        # Split on first '=' to separate key and value
        if "=" in segment:
            key, value = segment.split("=", 1)
        else:
            key = segment
            value = ""

        # Percent-decode and convert '+' to space
        key = urllib.parse.unquote_plus(key)
        value = urllib.parse.unquote_plus(value)

        # Add to result
        result.setdefault(key, []).append(value)

    return result

