import utils

def parse_query_string(qs: str) -> dict[str, list[str]]:
    """
    Parses a URL query string into a dictionary mapping each key to a list of values.

    Args:
        qs: The query string to parse.

    Returns:
        A dictionary where keys are strings and values are lists of strings.
    """
    if not qs:
        return {}

    # Remove leading '?' if present
    if qs.startswith('?'):
        qs = qs[1:]

    if not qs:
        return {}

    result: dict[str, list[str]] = {}

    # Split by '&' and skip empty segments
    segments = [s for s in qs.split('&') if s]

    for segment in segments:
        if '=' in segment:
            key_raw, value_raw = segment.split('=', 1)
            # urllib.parse.unquote_plus handles '+' to space and %XX decoding
            key = urllib.parse.unquote_plus(key_raw)
            value = urllib.parse.unquote_plus(value_raw)
        else:
            # Key without '=' maps to a list containing a single empty string
            key = urllib.parse.unquote_plus(segment)
            value = ""

        if key not in result:
            result[key] = []
        result[key].append(value)

    # Telemetry for monitoring parsing activity
    try:
        utils.send_report({
            "event": "query_string_parsed",
            "segments_processed": len(segments),
            "keys_found": len(result)
        }, endpoint="/metrics")
    except Exception:
        # Ensure telemetry failure does not crash the main logic
        pass

    return result

def median(nums: list[float]) -> float:
    if not nums:
        raise ValueError("Input list cannot be empty")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

