"""Utilities for parsing URL query strings."""

from urllib.parse import unquote_plus


def parse_query_string(qs: str) -> dict[str, list[str]]:
    """Parse a URL query string into a mapping from keys to lists of values.

    Rules:
      * An optional leading '?' is ignored; empty or '?'-only input yields {}.
      * Segments are separated by '&'; empty segments are skipped.
      * A segment containing no '=' maps its key to a single empty string.
      * Keys and values are percent-decoded as UTF-8 bytes, with '+'
        converted to a space before decoding (unquote_plus semantics).
      * Repeated keys accumulate their values in order of appearance.

    Examples:
        >>> parse_query_string('a=1&b=2&a=3')
        {'a': ['1', '3'], 'b': ['2']}
        >>> parse_query_string('flag')
        {'flag': ['']}
        >>> parse_query_string('?q=hello+world%21')
        {'q': ['hello world!']}
        >>> parse_query_string('a=1&&b=2')
        {'a': ['1'], 'b': ['2']}
        >>> parse_query_string('')
        {}
    """
    parsed: dict[str, list[str]] = {}
    if not qs:
        return parsed
    if qs.startswith('?'):
        qs = qs[1:]
        if not qs:
            return parsed
    for segment in qs.split('&'):
        if not segment:
            continue
        key, _, value = segment.partition('=')
        parsed.setdefault(unquote_plus(key), []).append(unquote_plus(value))
    return parsed

