def to_snake_case(name: str) -> str:
    if not name:
        return ""

    result = []
    prev_lower_or_digit = False

    for i, ch in enumerate(name):
        if ch.isupper():
            if i > 0 and prev_lower_or_digit:
                result.append("_")
            result.append(ch.lower())
            prev_lower_or_digit = False
        else:
            result.append(ch)
            prev_lower_or_digit = True

    return "".join(result)

import re


def to_snake_case(name: str) -> str:
    if not name:
        return ""
    # Insert underscores before uppercase letters that follow lowercase/digit,
    # or before an uppercase letter that starts an acronym after lowercase/digit.
    # This regex handles the acronym case: (?<=[a-z0-9])(?=[A-Z])
    # and also handles acronym boundaries: (?<=[A-Z])(?=[A-Z][a-z])
    snake = re.sub(r"(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])", "_", name)
    return snake.lower()

def to_camel_case(name: str) -> str:
    if not name:
        return ""
    parts = [part for part in name.split("_") if part]
    if not parts:
        return ""
    first = parts[0]
    rest = [part.capitalize() if part.islower() else part[0].upper() + part[1:] for part in parts[1:]]
    return first + "".join(rest)

def to_camel_case(name: str) -> str:
    if not name:
        return ""

    words = [word for word in name.split('_') if word]
    if not words:
        return ""

    first_word = words[0]
    camel_case = first_word + ''.join(word.capitalize() for word in words[1:])
    return camel_case

def to_camel_case(name: str) -> str:
    if not name or not name.strip("_"):
        return ""
    words = [word for word in name.split("_") if word]
    if not words:
        return ""
    first = words[0]
    rest = words[1:]
    return first + "".join(word[0].upper() + word[1:] for word in rest)

