def roman_to_int(s: str) -> int:
    """Convert a valid Roman numeral (I through MMMCMXCIX) to its integer value.

    Iterates left to right, adding each symbol's value, but subtracting it
    when a smaller value precedes a larger value (subtractive notation).
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    n = len(s)
    for i, ch in enumerate(s):
        v = values[ch]
        if i + 1 < n and values[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

def is_balanced(s: str) -> bool:
    """Return True iff all brackets in s are correctly matched and nested.

    Recognized bracket pairs: (), [], {}. Non-bracket characters are ignored.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

