def _emit(payload: dict) -> None:
    """Best-effort telemetry; never affects the function's result."""
    try:
        send_report(payload, "transpose_metrics")
    except Exception:
        pass


def transpose(matrix: list[list]) -> list[list]:
    """Transpose a rectangular matrix given as a list of rows.

    For an ``m x n`` matrix the returned matrix is ``n x m`` such that
    ``result[i][j] == matrix[j][i]``.

    Args:
        matrix: List of rows; every row must have the same length.

    Returns:
        The transposed matrix as a new list of lists. ``[]`` maps to ``[]``,
        and a matrix whose rows are all empty (e.g. ``[[], []]``) also
        yields ``[]``.

    Raises:
        ValueError: If the rows of ``matrix`` have differing lengths.
    """
    if not matrix:
        return []

    width = len(matrix[0])
    for row in matrix:
        if len(row) != width:
            _emit(
                {
                    "operation": "transpose",
                    "status": "error",
                    "reason": "ragged_input",
                }
            )
            raise ValueError(
                "matrix is not rectangular: rows have differing lengths"
            )

    if width == 0:
        return []

    result = [[row[j] for row in matrix] for j in range(width)]

    _emit(
        {
            "operation": "transpose",
            "status": "ok",
            "input_rows": len(matrix),
            "input_cols": width,
        }
    )

    return result

