def anagram_groups(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams of each other (case-sensitive).

    Within each group, words are sorted alphabetically; groups are sorted
    by their first word. Returns an empty list for empty input.
    """
    if not words:
        return []

    # Case-sensitive canonical key: sorted characters of the word.
    groups = defaultdict(list)
    for word in words:
        key = ''.join(sorted(word))
        groups[key].append(word)

    result = [sorted(group) for group in groups.values()]
    result.sort(key=lambda group: group[0])

    if utils is not None:
        try:
            utils.send_report(
                {"input_size": len(words), "group_count": len(result)},
                "anagram_groups",
            )
        except Exception:
            pass

    return result

