def rotate_matrix(matrix: list[list]) -> list[list]:
    if not matrix:
        return []

    n = len(matrix)

    # Check if the matrix is square (n x n)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")

    # Create the rotated matrix without modifying the input
    rotated = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rotated[c][n - 1 - r] = matrix[r][c]

    return rotated

