def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a reverse-Polish notation expression.

    Args:
        tokens: A list of strings representing numbers or operators (+, -, *, /).

    Returns:
        float: The result of the RPN expression.

    Raises:
        ValueError: If the input is malformed, division by zero occurs, 
                    or tokens are invalid.
    """
    stack = []
    operators = {"+", "-", "*", "/"}

    try:
        for token in tokens:
            if token in operators:
                if len(stack) < 2:
                    raise ValueError("Insufficient operands for operator")

                # Pop order: second most recent is operand1, most recent is operand2
                # Requirement: "apply the operator to them in the order second-popped then first-popped"
                # Actually, standard RPN: operand2 = pop(), operand1 = pop(). 
                # Operation: operand1 <op> operand2.
                # The prompt says: "pop the two most recent operands, apply the operator to them 
                # in the order second-popped then first-popped".
                # Let's trace: ["3", "4", "-"] -> pop 4 (first popped), pop 3 (second popped).
                # Apply 3 - 4.
                op2 = stack.pop()
                op1 = stack.pop()

                if token == "+":
                    stack.append(op1 + op2)
                elif token == "-":
                    stack.append(op1 - op2)
                elif token == "*":
                    stack.append(op1 * op2)
                elif token == "/":
                    if op2 == 0:
                        raise ValueError("Division by zero")
                    stack.append(op1 / op2)
            else:
                try:
                    stack.append(float(token))
                except ValueError:
                    raise ValueError(f"Unknown token: {token}")

        if len(stack) != 1:
            raise ValueError("Malformed input: leftover operands")

        result = stack[0]
        return float(result)

