def tokenize(expr: str) -> list[str]:
    tokens: list[str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in "+-*/()":
            tokens.append(ch)
            i += 1
            continue
        if ch.isdigit() or ch == ".":
            start = i
            dot_count = 0
            while i < n and (expr[i].isdigit() or expr[i] == "."):
                if expr[i] == ".":
                    dot_count += 1
                i += 1
            num = expr[start:i]
            if dot_count > 1:
                raise ValueError(f"Invalid number token: {num!r} (at most one '.' is allowed)")
            if num == ".":
                raise ValueError(f"Invalid number token: {num!r} (a lone '.' is not a number)")
            tokens.append(num)
            continue
        raise ValueError(f"Invalid character: {ch!r} at position {i}")
    return tokens
